.ds{--p-bg:#ffffff;--p-surface:#f1f3f6;--p-high:#fafbfc;--p-hover:#e1e6ed;--p-row-active:#e5e9f2;--p-disabled:#dce1e8;--p-glass:#f6f8fbe8;--p-backdrop:#2c333d66;--p-tile:#f2f3f0;--p-tile-header:#f3f4f1;--p-image-well:#e7e9e4;--p-selected-surface:#e7f0eb;--p-ink:#2c333d;--p-muted:#59636f;--p-on-accent:#ffffff;--p-line:#c2cad5;--p-line-subtle:#cbd2dc;--p-control-border:#7b8592;--p-edge:#ffffff;--p-edge-soft:#ffffffa8;--p-accent:#303b48;--p-accent-hover:#25303d;--p-shade:#000;--p-highlight:#6153b5;--p-highlight-soft:#e2ddf3;--p-soft:#d3e8de;--p-mark:#ffbf63;--p-mark-hover:#ffd07b;--p-mark-alt:#9ad9aa;--p-error:#a3313e;--p-error-soft:#f9e8e9;--p-error-line:#d4a2a8;--p-success:#26614f;--p-success-soft:#e5f2eb;--p-success-line:#8fb8a5;--p-warning:#805719;--p-warning-soft:#f6efd9;--p-warning-line:#b9a16f;--p-font:Pretendard, sans-serif;--p-display-font:Outfit, Pretendard, sans-serif;--p-text-sm:13px;--p-text-md:16px;--p-text-lg:24px;--p-space-xs:8px;--p-space-sm:12px;--p-space-md:16px;--p-space-lg:24px;--p-space-xl:32px;--p-radius:24px;--p-control-radius:16px;--p-inner-radius:12px;--p-shadow:6px 7px 16px #bbc4d166, -5px -5px 14px #ffffffed;--p-raised:3px 4px 8px #b9c3d066, -3px -3px 8px #ffffffed;--p-inset:inset 3px 3px 6px #b7c1cf55, inset -3px -3px 6px #ffffffd9;--p-pressed:inset 3px 3px 6px #15222f60,inset -1px -1px 3px #ffffff18;--p-float:0 12px 32px #26394d26;--p-lift:0 3px 5px #24314526;--p-control-shadow:0 3px 5px #24314526,inset 0 1px 0 #ffffff24;--p-selected-shadow:0 2px 5px #24314526;--p-knob-shadow:0 1px 3px #26344726;--p-glass-shadow:0 8px 24px #38465e12;--p-dialog-shadow:0 24px 80px #26344740;--p-drop:0 10px 12px #24293616;--p-ring:inset 0 0 0 2px #24293610;--p-focus-glow:0 0 0 2px #ed667b33;}
.ds {
  color:var(--p-ink); background:var(--p-bg); font:var(--p-text-md)/1.5 var(--p-font);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:3px solid var(--p-highlight); outline-offset:3px; }
.ds .ui-icon { display:inline-block; width:20px; height:20px; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--p-text-sm); margin-top:var(--p-space-sm); min-height:20px; color:var(--p-muted); }
.ds .ds-surface { border:1px solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--p-shadow); border-color:var(--p-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--p-inset); background:var(--p-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--p-high); box-shadow:var(--p-glass-shadow); }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--p-glass); backdrop-filter:blur(16px); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--p-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }

.ds .ds-search-module { container-type:inline-size; }
.ds .ds-search-form { display:grid; grid-template-columns:minmax(0,1fr) minmax(90px,.3fr) auto; align-items:end; gap:var(--p-space-sm); }
.ds .ds-result-count { font-size:var(--p-text-sm); color:var(--p-muted); margin-block:var(--p-space-lg) var(--p-space-md); }
.ds .ds-results { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,210px),1fr)); gap:var(--p-space-lg); }
.ds .ds-empty { padding:var(--p-space-xl); text-align:center; border:1px dashed var(--p-control-border); border-radius:var(--p-radius); }
.ds .ds-empty .ds-button { margin-top:var(--p-space-md); }
.ds .ds-record-detail { padding:var(--p-space-lg); border:1px solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-record-detail h3 { font-size:var(--p-text-lg); font-weight:650; }
.ds .ds-record-detail p { margin-top:var(--p-space-sm); color:var(--p-muted); }
.ds .ds-record-detail > div { display:flex; flex-wrap:wrap; gap:var(--p-space-sm); margin-top:var(--p-space-lg); }
.ds .ds-record-detail [aria-pressed="true"] { background:var(--p-success); border-color:var(--p-success); }
@media(max-width:580px) { .ds .ds-search-form { grid-template-columns:minmax(0,1fr) auto; } .ds .ds-search-form > .ds-field { grid-column:1/-1; } }
@container(max-width:580px) { .ds .ds-search-form { grid-template-columns:minmax(0,1fr) auto; } .ds .ds-search-form > .ds-field { grid-column:1/-1; } }
/* Looks. Labels hidden by a look stay in the page for screen readers. */
.ds .ds-search-module[data-look="pill"] :is(.ds-field > label,.ds-select-field > span),.ds .ds-chip-group > legend,.ds .ds-chip input { position:absolute; width:1px; height:1px; overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
/* 02 pill: query, status and button share one rounded bar */
.ds .ds-search-module[data-look="pill"] .ds-search-form { grid-template-columns:minmax(0,1fr) auto auto; align-items:center; gap:4px; padding:4px 4px 4px 12px; border:1px solid var(--p-control-border); border-radius:999px; background:var(--p-bg); box-shadow:var(--p-inset); }
.ds .ds-search-module[data-look="pill"] .ds-search-form > .ds-field { grid-column:auto; }
.ds .ds-search-module[data-look="pill"] .ds-search-form .ds-input { border:0; background:transparent; box-shadow:none; }
.ds .ds-search-module[data-look="pill"] .ds-search-form select.ds-input { width:auto; padding-inline:12px 8px; border-left:1px solid var(--p-line); border-radius:0; }
.ds .ds-search-module[data-look="pill"] .ds-search-form > .ds-button { border-radius:999px; }
@container(max-width:420px) { .ds .ds-search-module[data-look="pill"] .ds-search-form > .ds-button { gap:0; padding-inline:12px; font-size:0; } }
/* 03 chips: status as a row of chips under the query */
.ds .ds-search-module[data-look="chips"] .ds-search-form { grid-template-columns:minmax(0,1fr) auto; }
.ds .ds-search-module[data-look="chips"] .ds-search-form > .ds-field { grid-column:auto; }
.ds .ds-chip-group { grid-column:1/-1; order:3; display:flex; flex-wrap:wrap; gap:8px; min-width:0; margin:0; padding:0; border:0; }
.ds .ds-chip { position:relative; display:inline-flex; align-items:center; gap:6px; min-height:44px; padding:0 16px; border:1px solid var(--p-control-border); border-radius:999px; background:var(--p-bg); font-size:14px; cursor:pointer; }
.ds .ds-chip:has(:checked) { border-color:var(--p-accent); background:var(--p-accent); color:var(--p-on-accent); font-weight:650; }
.ds .ds-chip:has(:checked)::before { content:'✓'; font-weight:700; }
.ds .ds-chip:has(:focus-visible) { outline:3px solid var(--p-highlight); outline-offset:3px; }
/* list: results as rows instead of tiles */
.ds .ds-search-module[data-look="list"] .ds-results { grid-template-columns:minmax(0,1fr); gap:0; }
.ds .ds-search-module[data-look="list"] .ds-card { flex-flow:row wrap; align-items:center; border:0; border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-search-module[data-look="list"] .ds-card-body { flex:1 1 160px; padding:14px 0; }
.ds .ds-search-module[data-look="list"] .ds-card h3 { margin-top:4px; font-size:17px; }
.ds .ds-search-module[data-look="list"] .ds-divider { display:none; }
.ds .ds-search-module[data-look="list"] .ds-card-actions { padding:8px 0 8px 12px; }
.ds .ds-search-module[data-look="list"] .ds-results { border-top:1px solid var(--p-line); }
.ds .ds-search-module[data-look="list"] .ds-card { border-bottom:1px solid var(--p-line); }
/* 07 feature: the first result spans the row with a bigger title */
.ds .ds-search-module[data-look="feature"] .ds-results > :first-child { grid-column:1/-1; }
.ds .ds-search-module[data-look="feature"] .ds-results > :first-child h3 { font-size:26px; line-height:1.3; }
/* picker: one field that narrows while typing; every result is a face row tapped as a whole */
.ds .ds-search-module[data-look="picker"] .ds-search-form { grid-template-columns:minmax(0,1fr); }
.ds .ds-search-module[data-look="picker"] .ds-results { grid-template-columns:minmax(0,1fr); gap:0; border-top:1px solid var(--p-line); }
.ds .ds-search-module[data-look="picker"] .ds-card { position:relative; display:grid; grid-template-columns:44px minmax(0,1fr) auto; align-items:center; gap:var(--p-space-sm); padding:8px 4px; border:0; border-bottom:1px solid var(--p-line); border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-search-module[data-look="picker"] .ds-card-media { display:grid; place-items:center; flex:none; width:44px; height:44px; margin:0; aspect-ratio:auto; border-radius:50%; background:var(--p-soft); color:var(--p-ink); font-weight:700; }
.ds .ds-search-module[data-look="picker"] .ds-card-body { display:flex; flex-wrap:wrap; align-items:center; gap:2px 8px; padding:0; min-width:0; }
.ds .ds-search-module[data-look="picker"] .ds-card h3 { order:-1; margin:0; font-size:16px; }
.ds .ds-search-module[data-look="picker"] .ds-card p { flex-basis:100%; margin:0; font-size:13px; }
.ds .ds-search-module[data-look="picker"] .ds-card .ds-divider { display:none; }
.ds .ds-search-module[data-look="picker"] .ds-card-actions { grid-column:auto; padding:0; }
.ds .ds-search-module[data-look="picker"] .ds-card-actions .ds-button::after { content:''; position:absolute; inset:0; }

.ds .ds-field,.ds .ds-select-field { display:grid; gap:var(--p-space-xs); min-width:0; font-size:14px; }
.ds .ds-field > label,.ds .ds-select-field > span { font-weight:600; }
.ds .ds-help { font-size:var(--p-text-sm); color:var(--p-muted); line-height:1.5; }
.ds .ds-field[data-state="error"] .ds-help { color:var(--p-error); }
.ds .ds-field[data-state="error"] .ds-help::before { content:'!'; display:inline-grid; place-items:center; width:14px; height:14px; font-size:11px; border:1px solid currentColor; border-radius:50%; margin-right:5px; }
.ds .ds-field[data-state="success"] .ds-help { color:var(--p-success); }
.ds .ds-field[data-state="success"] .ds-help::before { content:'✓'; margin-right:5px; }
.ds .ds-field[data-state="success"] .ds-input { border-color:var(--p-success); }
.ds .ds-field[data-state="focus"] .ds-input { outline:3px solid var(--p-highlight); outline-offset:3px; }
/* looks: layout of label, input and help; input shapes come from the input part */
.ds .ds-field[data-look="inline"] { grid-template-columns:96px minmax(0,1fr); align-items:center; column-gap:var(--p-space-sm); }
.ds .ds-field[data-look="inline"] > .ds-help { grid-column:2; }
.ds .ds-field[data-look][data-state="success"] .ds-input { border-color:var(--p-success); }
.ds .ds-field[data-look="row"] .ds-input-group > .ds-input { text-align:center; }
.ds .ds-input-join { flex:none; color:var(--p-muted); }
.ds .ds-field[data-state="success"] .ds-input-group { border-color:var(--p-success); }
.ds .ds-field[data-state="focus"] .ds-input-group { outline:3px solid var(--p-highlight); outline-offset:3px; }
.ds .ds-field[data-state="focus"] .ds-input-group .ds-input { outline:0; }

.ds .ds-input { display:block; width:100%; min-width:0; min-height:48px; padding:11px 14px; border:1px solid var(--p-control-border); border-radius:var(--p-control-radius); background:var(--p-bg); box-shadow:var(--p-inset); color:var(--p-ink); font-size:14px; line-height:1.5; }
.ds .ds-input::placeholder { color:var(--p-muted); opacity:1; }
.ds .ds-input:disabled { opacity:1; box-shadow:none; color:var(--p-muted); background:var(--p-disabled); border-color:var(--p-line); cursor:not-allowed; }
.ds .ds-input[aria-invalid="true"] { border-color:var(--p-error); border-width:2px; padding:10px 13px; }
.ds label.ds-field { display:grid; gap:var(--p-space-xs); min-width:0; font-size:14px; }
/* looks: the same selector draws a bare input and the input inside a field of that look */
.ds .ds-field[data-look="float"] .ds-input { padding-top:14px; box-shadow:none; }
.ds .ds-field[data-look="float"] { position:relative; gap:0; }
.ds .ds-field[data-look="float"] > label { position:absolute; z-index:1; top:0; left:12px; transform:translateY(-50%); padding:0 6px; background:var(--p-bg); color:var(--p-muted); font-size:12px; line-height:1.4; }
.ds :is(.ds-input[data-look],.ds-field[data-look] .ds-input):disabled { background:var(--p-disabled); border-color:var(--p-line); color:var(--p-muted); box-shadow:none; }
.ds :is(.ds-input[data-look],.ds-field[data-look] .ds-input)[aria-invalid="true"] { border-color:var(--p-error); }
/* looks: the helper a value needs sits inside the same box — clear, unit, or − and + */
.ds .ds-input-group { display:flex; align-items:center; min-width:0; border:1px solid var(--p-control-border); border-radius:var(--p-control-radius); background:var(--p-bg); box-shadow:var(--p-inset); }
.ds .ds-input-group:focus-within { border-color:var(--p-accent); box-shadow:0 0 0 1px var(--p-accent); }
.ds .ds-input-group > .ds-input { flex:1 1 0; min-height:46px; border:0; border-radius:inherit; background:transparent; box-shadow:none; }
.ds .ds-input-group > .ds-input:focus-visible { outline:none; }
.ds .ds-input-tool { display:grid; place-items:center; flex:none; width:44px; height:44px; padding:0; border:0; border-radius:calc(var(--p-control-radius) - 2px); background:transparent; color:var(--p-ink); font:500 22px/1 var(--p-font); cursor:pointer; }
.ds .ds-input-tool:hover:not(:disabled) { background:var(--p-surface); }
.ds .ds-input-tool:focus-visible { outline-offset:-3px; }
.ds .ds-input-group[data-look="clear"] > .ds-input:placeholder-shown + .ds-input-tool { visibility:hidden; }
.ds .ds-input-group[data-look="unit"] > .ds-input { text-align:right; font-variant-numeric:tabular-nums; }
.ds .ds-input-unit { flex:none; align-self:stretch; min-height:44px; padding:0 12px; border:0; border-left:1px solid var(--p-line); border-radius:0 var(--p-control-radius) var(--p-control-radius) 0; background:transparent; color:var(--p-ink); font:inherit; font-weight:600; }
.ds .ds-input-unit:focus-visible { outline-offset:-3px; }
.ds .ds-input-group[data-look="stepper"] { width:fit-content; }
.ds .ds-input-group[data-look="stepper"] > .ds-input { flex:0 0 64px; padding-inline:4px; text-align:center; font-variant-numeric:tabular-nums; -moz-appearance:textfield; appearance:textfield; }
.ds .ds-input-group[data-look="stepper"] > .ds-input::-webkit-inner-spin-button { -webkit-appearance:none; margin:0; }
.ds .ds-input-group:has(:disabled) { background:var(--p-disabled); border-color:var(--p-line); box-shadow:none; color:var(--p-muted); }
.ds .ds-input-group:has(:disabled) .ds-input-tool { color:var(--p-muted); cursor:not-allowed; }
.ds .ds-input-group:has([aria-invalid="true"]) { border-color:var(--p-error); box-shadow:0 0 0 1px var(--p-error); }

.ds .ds-button { display:inline-flex; justify-content:center; align-items:center; gap:var(--p-space-xs); min-width:48px; min-height:48px; padding:10px 20px; border:1px solid var(--p-accent); border-radius:var(--p-control-radius); background:var(--p-accent); color:var(--p-on-accent); font-size:14px; font-weight:650; line-height:1.4; box-shadow:var(--p-control-shadow); text-decoration:none; transition:background var(--p-duration),box-shadow var(--p-duration); }
.ds .ds-button[data-variant="outline"] { border-color:var(--p-control-border); color:var(--p-ink); background:var(--p-surface); box-shadow:var(--p-raised); }
.ds .ds-button[data-variant="ghost"] { color:var(--p-ink); background:transparent; border-color:transparent; box-shadow:none; }
.ds .ds-button[data-size="sm"] { min-height:44px; min-width:44px; padding:8px 16px; font-size:13px; }
.ds .ds-button[data-size="lg"] { min-height:56px; min-width:56px; padding:14px 24px; font-size:16px; }
.ds .ds-button[data-icon-only] { padding:10px; }
.ds .ds-button:not(:disabled):is(:hover,[data-state="hover"]) { background:color-mix(in srgb,var(--p-accent) 84%,var(--p-shade)); }
.ds .ds-button[data-variant="outline"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--p-high); }
.ds .ds-button[data-variant="ghost"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--p-disabled); }
.ds .ds-button:not(:disabled):is(:active,[data-state="pressed"]) { box-shadow:var(--p-pressed); }
.ds .ds-button:not([data-variant="primary"]):not(:disabled):is(:active,[data-state="pressed"]) { background:var(--p-bg); box-shadow:var(--p-inset); }
.ds .ds-button[data-state="focus"] { outline:3px solid var(--p-highlight); outline-offset:3px; }
.ds .ds-button:disabled { opacity:1; box-shadow:none; background:var(--p-disabled); border-color:var(--p-line); color:var(--p-muted); }
.ds .ds-button[aria-busy="true"] { background:var(--p-accent); color:var(--p-on-accent); border-color:var(--p-accent); }
.ds .ds-spinner { width:16px; height:16px; flex-shrink:0; border:2px solid currentColor; border-right-color:transparent; border-radius:50%; animation:ds-spin .8s linear infinite; }
@keyframes ds-spin { to { transform:rotate(360deg); } }
@media(prefers-reduced-motion:reduce) { .ds .ds-spinner { border-style:dotted; } }
/* looks: primary colors change per look, pill/cta change shape for every variant; disabled keeps the base state */
/* looks: arrangements of actions; colour roles stay on data-variant */
.ds .ds-actions { display:flex; flex-wrap:wrap; align-items:center; gap:var(--p-space-xs); min-width:0; }
.ds .ds-button-count { display:inline-grid; place-items:center; min-width:22px; height:22px; padding:0 6px; border-radius:99px; background:var(--p-accent); color:var(--p-on-accent); font-size:12px; font-weight:700; line-height:1; }
.ds .ds-button[data-variant="primary"] .ds-button-count { background:var(--p-on-accent); color:var(--p-accent); }
.ds .ds-actions[data-look="hero"] { flex-wrap:nowrap; gap:0; }
.ds .ds-actions[data-look="hero"] > .ds-button:first-child { flex:1 0 auto; margin-right:var(--p-space-xs); padding-inline:16px; white-space:nowrap; }
.ds .ds-actions[data-look="hero"] > .ds-button[data-icon-only] { flex:none; width:44px; min-width:44px; padding:0; }
.ds .ds-actions[data-look="hero"] > .ds-button[data-icon-only] { color:var(--p-ink); }
.ds .ds-actions[data-look="pair"] { justify-content:flex-end; }
.ds .ds-actions[data-look="pair"] > .ds-button { flex:0 1 auto; }
.ds .ds-actions[data-look="bar"] { width:100%; padding:var(--p-space-sm); border-top:1px solid var(--p-line); background:var(--p-bg); }
.ds .ds-actions[data-look="bar"] > .ds-button { flex:1; min-height:52px; }

.ds .ds-badge { display:inline-flex; align-items:center; width:fit-content; padding:4px 10px; border:1px solid var(--p-line); border-radius:99px; background:var(--p-soft); color:var(--p-ink); font-size:12px; line-height:1.5; font-weight:600; }
.ds .ds-badge[data-tone="success"] { background:var(--p-success-soft); border-color:var(--p-success-line); color:var(--p-success); }
.ds .ds-badge[data-tone="error"] { background:var(--p-error-soft); border-color:var(--p-error-line); color:var(--p-error); }
.ds .ds-badge[data-tone="warning"] { background:var(--p-warning-soft); border-color:var(--p-warning-line); color:var(--p-warning); }
/* looks: tone keeps the color, look changes the shape */
.ds .ds-badge[data-look="dot"] { gap:6px; background:var(--p-bg); }
.ds .ds-badge[data-look="dot"]::before { content:''; width:8px; height:8px; border-radius:50%; background:currentColor; }
.ds .ds-badge[data-look="icon"] { gap:4px; padding-left:8px; }
.ds .ds-badge[data-look="icon"] .ui-icon { width:14px; height:14px; stroke-width:2.4; }

.ds .ds-card { display:flex; flex-direction:column; height:100%; background:var(--p-surface); border:1px solid var(--p-line); border-radius:var(--p-radius); box-shadow:var(--p-raised); overflow:hidden; }
.ds .ds-card[data-selected="true"] { border-color:var(--p-success); background:var(--p-selected-surface); }
.ds .ds-card-body { flex:1; padding:var(--p-space-lg); }
.ds .ds-card h3 { font-size:20px; line-height:1.45; font-weight:650; letter-spacing:-.035em; margin-top:var(--p-space-md); }
.ds .ds-card p { font-size:14px; color:var(--p-muted); margin-top:var(--p-space-xs); }
.ds .ds-card-actions { display:flex; justify-content:flex-end; padding:var(--p-space-md) var(--p-space-lg); }
/* Looks: :where keeps each look as weak as the base rule, so a selected card still shows its selected state. */
.ds .ds-card:where([data-look="row"]) { display:grid; grid-template-columns:88px minmax(0,1fr); align-content:start; }
